@dataclass(frozen=True)
class Address:
    library: str = field()
    spec: Literal["models", "templates", "values", "posets", "primitivedps", "interfaces", "queries"] = field()
    thing: str = field()
    type_: Literal["Address"] = field()
    repo: str | None = field(metadata={'description': "The Git repository URL"})

